import{_ as s,o as a,c as i,a0 as t}from"./chunks/framework.B_k70FqT.js";const k=JSON.parse('{"title":"示例应用","description":"","frontmatter":{},"headers":[],"relativePath":"guide/examples.md","filePath":"guide/examples.md","lastUpdated":1795867940000}'),d={name:"guide/examples.md"};function o(l,e,p,c,h,n){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="示例应用" tabindex="-1">示例应用 <a class="header-anchor" href="#示例应用" aria-label="Permalink to &quot;示例应用&quot;">​</a></h1><p>仓库里有两个可直接运行的应用：一个功能完整的编辑器，一个最小集成示例。它们同时也是示例快照测试的输入——图能不能被加载、序列化是否稳定，都由 <code>pnpm test</code> 兜底。</p><h2 id="完整编辑器-apps-editor" tabindex="-1">完整编辑器 <code>apps/editor</code> <a class="header-anchor" href="#完整编辑器-apps-editor" aria-label="Permalink to &quot;完整编辑器 `apps/editor`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @litegraph/editor</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>编辑器在最小示例之上补齐了这些能力：</p><ul><li>工具栏：运行/暂停、保存/加载、清空、最大化、小窗预览、live mode 切换；</li><li>示例下拉框：内置 demo 与 <code>public/examples/*.json</code> 都可以一键加载，加载后自动缩放到整张图；</li><li>本地恢复：关闭页面时自动备份当前图到 <code>localStorage</code>，下次打开自动恢复（也可从下拉框手动切回）；</li><li>工具栏 <code>Fit</code> 按钮：随时缩放到整张图，进入子图后同样可用；</li><li>节点搜索框：按类型/标题搜索节点，拖到画布即创建；</li><li>右键菜单、属性面板、widget 交互、框选、对齐吸附、分组；</li><li>两个编辑器专属插件：<code>features/*</code>（插槽/控件/形状等演示节点）与 <code>circuit/*</code>（振荡器、LED），在 <code>apps/editor/src/Editor.ts</code> 中通过 <code>LiteGraph.use()</code> 安装。</li></ul><h3 id="内置-demo" tabindex="-1">内置 demo <a class="header-anchor" href="#内置-demo" aria-label="Permalink to &quot;内置 demo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>内容</th></tr></thead><tbody><tr><td><code>Basic1</code></td><td>一个常量接一个 watch</td></tr><tr><td><code>Basic2</code></td><td>两个常量分别接 watch</td></tr><tr><td><code>Basic3</code></td><td>两个常量 + 数学运算 + 三个 watch</td></tr><tr><td><code>Widgets</code></td><td>旋钮 → 进度条、开关 → watch、按钮事件 → 日志</td></tr><tr><td><code>Events</code></td><td>定时器 → 计数器 → watch，并记录每次 change 事件</td></tr><tr><td><code>Subgraph</code></td><td>内层图「Add 10」：常量 → 子图 → watch，双击子图节点进入/返回</td></tr><tr><td><code>Audio1</code></td><td><code>audio/source</code> → <code>audio/destination</code></td></tr><tr><td><code>Audio2</code></td><td>音源 + 旋钮 + 分析器 + 可视化</td></tr><tr><td><code>Audio3</code></td><td>在 Audio2 基础上加示波器</td></tr><tr><td><code>Circuit1</code></td><td><code>circuit/oscillator</code> → <code>circuit/led</code></td></tr></tbody></table><h3 id="内置-json-示例" tabindex="-1">内置 JSON 示例 <a class="header-anchor" href="#内置-json-示例" aria-label="Permalink to &quot;内置 JSON 示例&quot;">​</a></h3><p>这些文件位于 <code>apps/editor/public/examples/</code>，由编辑器通过 <code>graph.load(url)</code> 加载：</p><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>features.json</code></td><td><code>features/slots</code>、<code>features/widgets</code>、<code>features/shape</code>、<code>features/properties_editor</code> 四类演示节点</td></tr><tr><td><code>benchmark.json</code></td><td>大量节点与连线的性能基准图</td></tr><tr><td><code>subgraph.json</code></td><td>子图与 <code>graph/input</code>、<code>graph/output</code></td></tr><tr><td><code>audio.json</code></td><td>较完整的音频处理链</td></tr><tr><td><code>audio_delay.json</code></td><td>延迟节点示例</td></tr><tr><td><code>audio_reverb.json</code></td><td>混响节点示例</td></tr><tr><td><code>midi_generation.json</code></td><td>MIDI 生成、量化与播放</td></tr></tbody></table><h3 id="live-mode" tabindex="-1">live mode <a class="header-anchor" href="#live-mode" aria-label="Permalink to &quot;live mode&quot;">​</a></h3><p>编辑器工具栏右侧的 <code>LIVE</code> 按钮切换 <code>graphCanvas.live_mode</code>：隐藏网格、节点边框、插槽与标题栏，只保留节点自绘内容。适合把编辑器当作运行时界面使用，例如做音频可视化或参数面板。</p><h2 id="最小示例-apps-example-minimal" tabindex="-1">最小示例 <code>apps/example-minimal</code> <a class="header-anchor" href="#最小示例-apps-example-minimal" aria-label="Permalink to &quot;最小示例 `apps/example-minimal`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @litegraph/example-minimal</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>src/main.ts</code> 只有几十行：引入 core 与 <code>basic</code> 节点包、引入样式、创建 <code>LGraph</code> 与 <code>LGraphCanvas</code>、放一个 <code>ConstantNumber</code> 和一个 <code>Watch</code>、连线并 <code>graph.start()</code>。它演示了：</p><ul><li>显式引入 <code>@gausszhou/litegraph-core/style.css</code>；</li><li>用类而不是类型字符串创建节点（<code>LiteGraph.createNode(ConstantNumber)</code>）；</li><li>在 <code>onAfterExecute</code> 中重绘画布；</li><li>监听窗口 resize 并调用 <code>graphCanvas.resize()</code>。</li></ul><p>这份示例也是快照基线之一：测试里按相同方式构造 <code>ConstantNumber(4.5) → Watch</code>，断言 2 个节点、1 条连接，并序列化做快照。</p><h2 id="导入与导出图" tabindex="-1">导入与导出图 <a class="header-anchor" href="#导入与导出图" aria-label="Permalink to &quot;导入与导出图&quot;">​</a></h2><p>编辑器保存出来的就是 <code>graph.serialize()</code> 的结果；在任何环境下都可以这样恢复：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> graph</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LGraph</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">graph.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">JSON</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(json));</span></span></code></pre></div><p>加载一个包含未知节点类型的图不会抛异常：<code>configure()</code> 会返回 <code>true</code>，并用错误节点替换缺失的节点。想提前发现缺包，可以检查返回值：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (graph.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(data)) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">warn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;图里有未注册的节点类型，请安装对应节点包&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="示例快照回归" tabindex="-1">示例快照回归 <a class="header-anchor" href="#示例快照回归" aria-label="Permalink to &quot;示例快照回归&quot;">​</a></h2><p><code>packages/tests/src/ExamplesSnapshotTests.ts</code> 把示例纳入自动化回归，覆盖 18 个用例：</p><ul><li><code>apps/editor/public/examples/*.json</code> 中的全部 JSON：<code>configure()</code> 返回 <code>false</code>、节点数量与文件一致、序列化 → 再 <code>configure()</code> → 再序列化的结果深相等；</li><li><code>apps/editor/src/demos.ts</code> 中的 10 个函数式 demo：构建后节点数 &gt; 0 且序列化稳定；</li><li>最小示例基线：<code>ConstantNumber(4.5) → Watch</code>。</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 全量</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @gausszhou/litegraph-tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>另外 <code>pnpm demo:smoke</code> 会用本机 Chrome / Chromium 打开构建后的 demo，逐个切换示例并检查：画布与 Empty 状态有像素差异、节点与连线数量大于 0、所有节点在 Fit 后位于视口内、没有 JS 异常或 console.error。加 <code>-- --screenshots</code> 会把每个示例的画布截图写到 <code>artifacts/demo-smoke/</code>；CI 会执行这一步并上传截图 artifact（需要先 <code>pnpm build</code> 或单独构建 editor）。</p><p>快照文件在 <code>packages/tests/src/__snapshots__/main.ts.snap</code>。<strong>只有在确认序列化格式的变更是有意为之</strong>时才更新快照：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @gausszhou/litegraph-tests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span></span></code></pre></div><p>新增示例的步骤：</p><ol><li>把图 JSON 放进 <code>apps/editor/public/examples/</code>；</li><li>在 <code>apps/editor/src/main.ts</code> 的 <code>addDemo(...)</code> 列表里注册；</li><li>如果用到编辑器专属节点（<code>features/*</code>、<code>circuit/*</code>），确认对应插件已在 <code>Editor.ts</code> 中安装；</li><li>跑 <code>pnpm test</code>，首次会为新增文件生成快照；再跑一次确认稳定后提交快照。</li></ol>',32)])])}const g=s(d,[["render",o]]);export{k as __pageData,g as default};
